    if (!reachable(pc)) continue;
    // every reachable instruction gets a label
    fprintf(out, "L_%llx:\n", pc);
    switch (inst.op) {
    case OP_ADD:
        // fall-through: no goto emitted at all
        fprintf(out, "\t%s = %s + %s;\n", reg_name(inst.rd), reg_name(inst.rs1), reg_name(inst.rs2));
        break;
